/** Sample posts for the posts block. */
export function samplePosts(locale: L, cover: (n: number) => string | null): Raw[] {
   const t = locale === 'ar' ? ['كيف ترفع أول مرئي', 'سمات جديدة للموقع', 'البث المباشر في رمضان'] : ['How to upload your first video', 'New themes for the site', 'Live streams in Ramadan'];
   const x = locale === 'ar' ? ['خطوات قصيرة من الحساب إلى النشر.', 'أربع سمات، فاتحة وداكنة.', 'جدول البث لهذا الشهر.'] : ['A few short steps from account to publish.', 'Four themes, light and dark.', 'This month’s live schedule.'];
   return t.map((title, i) => {
      const url = cover(i + 2);
      return { slug: `sample-post-${i + 1}`, locale, title, excerpt: x[i], cover: url ? { url, alt: null, width: 1200, height: 750, variants: null } : null, published_at: `2026-11-${String(10 + i).padStart(2, '0')}T09:00:00.000Z`, author_name: null, kind: 'article' };
   });
}

/**
 * Lookups for `servePageBlocks` over the sample: media id → `media(id)` URL (1200×750), the sample
 * videos with `thumb(key)` thumbnails, and the sample posts.
 */
export function sampleServeRefs(locale: L, media: (id: number) => string | null, thumb: (key: string) => string | null) {
   return {
      media: (id: number) => {
         const url = media(id);
         return url ? { url, alt: null, width: 1200, height: 750, variants: null } : null;
      },
      snapshot: (kind: string, refId: string) => {
         const key = `${kind}:${refId}`;
         const v = SAMPLE_VIDEOS[key];
         return v ? { ...v, thumbnail_url: thumb(key) } : null;
      },
      posts: () => samplePosts(locale, media) as never[],
   };
}
